IsLocalization.map_map.{u_1, u_2, u_3, u_4, u_5, u_6} {R : Type u_1} [CommSemiring R] {M : Submonoid R} {S : Type u_2}
  [CommSemiring S] [Algebra R S] {P : Type u_3} [CommSemiring P] [IsLocalization M S] {g : R →+* P} {T : Submonoid P}
  {Q : Type u_4} [CommSemiring Q] (hy : M ≤ Submonoid.comap g T) [Algebra P Q] [IsLocalization T Q] {A : Type u_5}
  [CommSemiring A] {U : Submonoid A} {W : Type u_6} [CommSemiring W] [Algebra A W] [IsLocalization U W] {l : P →+* A}
  (hl : T ≤ Submonoid.comap l U) (x : S) :
  (IsLocalization.map W l hl) ((IsLocalization.map Q g hy) x) = (IsLocalization.map W (l.comp g) ⋯) x
